def poll_cron(exp_id: str, nan_metric: str = "train_loss") -> ToolResult:
    """Poll a single experiment: check process + W&B metrics + anomaly detection.

    State transitions triggered:
      - NaN detected in nan_metric  → kill job → registry DONE(killed) → delete cron
      - Process exited + W&B OK     → registry RUNNING → ANALYZING → delete cron
      - Process exited + no W&B     → registry RUNNING → DONE(failed) → delete cron
      - Process still running       → update last_checked timestamp only

    Args:
        exp_id: Experiment identifier to poll.
        nan_metric: W&B metric name to check for NaN (default "train_loss").

    Returns:
        ToolResult with actions taken and running status.
    """
    crons = _read_crons()
    entry = next((c for c in crons if c["exp_id"] == exp_id), None)
    if entry is None:
        return ToolResult(success=False, error=f"No cron registered for '{exp_id}'.")

    # Skip entries with pending hook retries — handled by _flush_pending_hooks
    if entry.get("_pending_hook"):
        _log_poll(entry, ssh_ok=None, process_alive=None, wandb_state=None,
                  wandb_has_metrics=False, metrics_snapshot=None,
                  action_taken="skip_pending_hook",
                  reason=f"Pending hook retry: {entry['_pending_hook']}")
        return ToolResult(
            success=True,
            data={
                "exp_id": exp_id,
                "was_running": False,
                "actions": [f"Skipped — pending hook retry ({entry['_pending_hook']})"],
            },
        )

    # Skip entries with pending escalation retries — handled by _flush_pending_escalations
    if entry.get("_pending_escalation"):
        _log_poll(entry, ssh_ok=None, process_alive=None, wandb_state=None,
                  wandb_has_metrics=False, metrics_snapshot=None,
                  action_taken="skip_pending_escalation",
                  reason="Pending escalation retry")
        return ToolResult(
            success=True,
            data={
                "exp_id": exp_id,
                "was_running": False,
                "actions": ["Skipped — pending escalation retry"],
            },
        )

    actions: list[str] = []
    _proj = entry.get("project")

    # Fast-exit: if registry already shows this experiment as DONE/ANALYZING,
    # the cron is stale (e.g. tmux session lingered after completion).
    # IMPORTANT: verify the process is actually dead before deleting the cron —
    # a stale registry write (race condition) can cause false positives.
    if _proj:
        try:
            import yaml as _yaml2
            reg_path = _paths.resolve_project_file(_proj, "registry.yaml")
            if reg_path.exists():
                _reg2 = _yaml2.safe_load(reg_path.read_text()) or {}
                _status = _reg2.get("experiments", {}).get(exp_id, {}).get("status", "")
                if _status in ("DONE", "ANALYZING", "DEPLOYED"):
                    # Verify the process is actually dead before trusting the registry.
                    verify = _get_check_job_status()(entry["server"], entry["pid"], exp_id=exp_id)
                    if verify.success and verify.data.get("running"):
                        logger.error(
                            "[cron] Registry=%s but process still alive for %s "
                            "(server=%s pid=%s) — skipping fast-exit to avoid false positive",
                            _status, exp_id, entry["server"], entry["pid"],
                        )
                    else:
                        delete_cron(exp_id)
                        logger.info(
                            "[cron] stale cron removed: %s already %s in registry", exp_id, _status
                        )
                        _log_poll(entry, ssh_ok=True, process_alive=False,
                                  wandb_state=None, wandb_has_metrics=False,
                                  metrics_snapshot=None,
                                  action_taken="stale_cron_removed",
                                  reason=f"Registry already {_status}, process dead")
                        return ToolResult(
                            success=True,
                            data={"exp_id": exp_id, "actions": [f"Stale cron removed (registry status={_status})"]},
                        )
        except Exception:
            pass

    # Defensive: try to resolve project from all known registries if not stored
    if not _proj:
        from core import paths as _p
        try:
            import yaml as _yaml
            for proj_dir in (_p.WORKSPACE_ROOT / "projects").iterdir():
                reg_path = proj_dir / "registry.yaml"
                if reg_path.exists():
                    _reg = _yaml.safe_load(reg_path.read_text()) or {}
                    if exp_id in _reg.get("experiments", {}):
                        _proj = proj_dir.name
                        # Persist so future polls don't need to re-scan
                        crons2 = _read_crons()
                        for c in crons2:
                            if c["exp_id"] == exp_id:
                                c["project"] = _proj
                                break
                        _write_crons(crons2)
                        entry["project"] = _proj
                        logger.info("[cron] resolved missing project=%s for %s", _proj, exp_id)
                        break
        except Exception:
            logger.warning("[cron] failed to resolve project for %s", exp_id)

    # 1. Check process status — pass exp_id so check_job_status can use the
    # exit sentinel fast path (`/tmp/agent-ml-exit/<exp_id>.exit`) and avoid
    # the ps/tmux roundtrip cost + ambiguity entirely when the job has ended.
    status_result = _get_check_job_status()(entry["server"], entry["pid"], exp_id=exp_id)

    # Authoritative exit_code from the sentinel (when fast path hit). Threads
    # through to _extract_failure_reason so "EXIT_CODE=124 (timeout)" etc.
    # shows up in registry.failure_reason without re-reading the log.
    _sentinel_exit: int | None = None
    if status_result.success and status_result.data.get("detection") == "sentinel":
        _sc = status_result.data.get("exit_code")
        if isinstance(_sc, int):
            _sentinel_exit = _sc

# Validate GPUs (with collision detection)
# Note: exclude the current experiment from occupied check — when called
# from submit_on_allocated, the experiment is already ALLOCATED with these
# GPUs, so it would otherwise block itself.
try:
    from core.tools.gpu_allocator import get_truly_available_gpus, get_occupied_gpus, invalidate_gpu_cache
    invalidate_gpu_cache()
    occupied = get_occupied_gpus()
    # Build available list excluding self from occupied
    config_available = set(_get_available_gpu_ids(server))
    occupied_by_others = {
        gpu_id for (srv, gpu_id), (eid, _) in occupied.items()
        if srv == server and eid != exp_id
    }
    available = sorted(config_available - occupied_by_others)
except ImportError:
    available = _get_available_gpu_ids(server)
    occupied = {}

for gid in gpu_ids:
    if gid not in available:
        occupant = occupied.get((server, gid))
        if occupant and occupant[0] != exp_id:
            return ToolResult(
                success=False,
                error=f"GPU {gid} is occupied by experiment '{occupant[0]}' (project: {occupant[1]}). Available: {available}",
                metadata={"elapsed_seconds": 0},
            )
        return ToolResult(
            success=False,
            error=f"GPU {gid} is not available. Available: {available}",
            metadata={"elapsed_seconds": 0},
        )

# Resolve work_dir: explicit > project_path > account > server > ~
resolved = _resolve_account(server, account)
resources = _load_resources()
srv_cfg = resources.get("servers", {}).get(server, {})
project_work_dir = _resolve_project_work_dir(project, server, account)
resolved_work_dir = work_dir or project_work_dir or resolved.work_dir or srv_cfg.get("work_dir", "~")
if resolved_work_dir in ("~", "") and project:
    return ToolResult(
        success=False,
        error=(
            f"work_dir resolved to '{resolved_work_dir}' for project '{project}'. "
            f"Set execution.project_path in the project config "
            f"(via update_project_config) to specify the remote working directory."
        ),
        metadata={"elapsed_seconds": 0},
    )
# env_activate priority: account > server > project config
env_activate = resolved.env_activate or srv_cfg.get("env_activate", "")
if not env_activate and project:
    try:
        from core.tools.project_config import load_project_config
        cfg_result = load_project_config(project)
        if cfg_result.success:
            env_activate = cfg_result.data.get("config", {}).get("execution", {}).get("env_activate", "")
    except Exception:
        pass
# Validate work_dir
try:
    _validate_path(resolved_work_dir, "work_dir")
except ValueError as e:
    return ToolResult(success=False, error=str(e), metadata={"elapsed_seconds": 0})

# Resolve execution backend (tmux or slurm) from server config
from core.tools.execution_backends import get_execution_backend, get_backend_name
backend = get_execution_backend(server, srv_cfg)
backend_name = get_backend_name(server, srv_cfg)

# Slurm runs under bash natively; bash-wrapper check only applies to tmux
if backend_name == "tmux":
    _wrap_err = _check_bash_wrapper(command)
    if _wrap_err:
        return ToolResult(
            success=False,
            error=_wrap_err,
            metadata={"elapsed_seconds": 0, "validator": "bash_wrapper"},
        )

log_file = _resolve_project_log_dir(project, exp_id)
log_dir = "/".join(log_file.rsplit("/", 1)[:-1])
timeout_secs = int(timeout_hours * 3600)
cvd = ",".join(g.split(":", 1)[1] if ":" in g else g for g in gpu_ids)

# Inject W&B API key if configured (encrypted file > env var)
wandb_key = ""
try:
    from core.crypto import load_secret
    from core import paths as _paths_mod
    wandb_key = load_secret(_paths_mod.config_dir() / "wandb_api_key.enc") or ""
except Exception:
    pass
if not wandb_key:
    wandb_key = os.environ.get("WANDB_API_KEY", "")

sentinel_dir = "/tmp/agent-ml-exit"
if backend_name == "slurm":
    slurm_cfg = srv_cfg.get("slurm", {})
    sentinel_dir = slurm_cfg.get("sentinel_dir", "~/.agent-ml-exit")

try:
    conn = _get_connection(server, account)
    submit_result = backend.submit_job(
        conn,
        exp_id=exp_id,
        command=command,
        gpu_ids=gpu_ids,
        work_dir=resolved_work_dir,
        log_file=log_file,
        log_dir=log_dir,
        env_activate=env_activate,
        timeout_secs=timeout_secs,
        wandb_key=wandb_key,
        cvd=cvd,
        sentinel_dir=sentinel_dir,
    )

    if not submit_result.success:

